-- Migration: tablas jerarquicas de ubicacion Peru
-- Source: C:/Users/USUARIO/Downloads/FormularioAsistencia.xlsx

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS location_departments (
  iddepartamento TEXT PRIMARY KEY,
  idpais INTEGER NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS location_provinces (
  idprovincia TEXT PRIMARY KEY,
  idpais INTEGER NOT NULL,
  iddepartamento TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (iddepartamento) REFERENCES location_departments(iddepartamento) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS location_districts (
  iddistrito TEXT PRIMARY KEY,
  idpais INTEGER NOT NULL,
  idprovincia TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (idprovincia) REFERENCES location_provinces(idprovincia) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_location_provinces_department ON location_provinces(iddepartamento, status);
CREATE INDEX IF NOT EXISTS idx_location_districts_province ON location_districts(idprovincia, status);



